:scope .chapter-container {
  font-family: var(--font-serif, serif);
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  line-height: 1.6;
}

:scope .chapter-header h1 {
  font-size: 1.8rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
  border-bottom: 2px solid var(--accent);
  display: inline-block;
}

:scope .meta-info {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
}

:scope .badge {
  background: var(--muted);
  color: var(--paper);
  padding: 0.2rem 0.6rem;
  border-radius: 4px;
  font-size: 0.85rem;
  font-family: var(--font-sans, sans-serif);
}

:scope .content-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 2rem;
}

@media (max-width: 768px) {
  :scope .content-grid {
    grid-template-columns: 1fr;
  }
}

:scope .viz-card {
  background: #f8f9fa;
  border: 1px solid var(--line);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  border-radius: 6px;
}

:scope .viz-card h3 {
  font-family: var(--font-sans, sans-serif);
  font-size: 1.1rem;
  margin-top: 0;
  color: var(--accent);
}

:scope .year-toggle {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

:scope .year-toggle button {
  background: transparent;
  border: 1px solid var(--line);
  padding: 0.4rem 1rem;
  cursor: pointer;
  font-family: var(--font-sans, sans-serif);
  color: var(--muted);
}

:scope .year-toggle button.active,
:scope .year-toggle button[aria-pressed="true"] {
  background: var(--accent);
  color: var(--paper);
  border-color: var(--accent);
}

:scope .cloud-container {
  min-height: 200px;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-content: flex-start;
  font-family: var(--font-sans, sans-serif);
}

:scope .cloud-word {
  padding: 0.2rem 0.5rem;
  background: #e9ecef;
  border-radius: 3px;
  font-size: 0.9rem;
  transition: transform 0.2s;
}

:scope .cloud-word:hover {
  transform: scale(1.1);
  background: var(--accent);
  color: var(--paper);
}

:scope .cloud-word.highlight {
  background: var(--warm);
  color: var(--paper);
  font-weight: bold;
}

:scope .chart-wrapper {
  width: 100%;
  height: 200px;
  margin-bottom: 1rem;
}

:scope .legend {
  display: flex;
  gap: 1rem;
  font-size: 0.85rem;
  font-family: var(--font-sans, sans-serif);
  color: var(--muted);
}

:scope .legend-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

:scope .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

:scope .dot.bb { background: var(--accent); }
:scope .dot.msd { background: var(--muted); }

:scope .analysis-panel {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

:scope .argument-block {
  background: var(--paper);
  padding: 1rem;
  border-left: 3px solid var(--line);
}

:scope .warning-block {
  border-left-color: var(--warm);
  background: #fff5f5;
}

:scope .limitation-text {
  font-size: 0.9rem;
  color: #d63030;
  font-style: italic;
}

:scope .source-bar {
  margin-top: 1rem;
  display: flex;
  gap: 0.5rem;
  border-top: 1px solid var(--line);
  padding-top: 0.5rem;
}

:scope button.source-btn,
:scope button.concept-btn,
:scope button.ask-btn {
  font-size: 0.8rem;
  padding: 0.3rem 0.6rem;
  border: 1px solid var(--line);
  background: transparent;
  cursor: pointer;
  font-family: var(--font-sans, sans-serif);
  color: var(--ink);
}

:scope button.source-btn:hover {
  background: var(--muted);
  color: var(--paper);
}

:scope .mini-viz {
  margin-top: 0.5rem;
  padding: 0.5rem;
  background: #f1f3f5;
  border-radius: 4px;
}

:scope .track {
  display: flex;
  align-items: flex-end;
  height: 40px;
  gap: 1rem;
}

:scope .bar {
  width: 60px;
  text-align: center;
  color: var(--paper);
  font-size: 0.8rem;
  font-family: var(--font-sans, sans-serif);
  padding-top: 4px;
}

:scope .bar.rock {
  height: 80%;
  background: var(--accent);
}

:scope .bar.blues {
  height: 40%;
  background: var(--muted);
}

:scope .caption {
  display: block;
  font-size: 0.75rem;
  color: var(--muted);
  margin-top: 4px;
  text-align: center;
}

