(function() {
  'use strict';

  // Data Access
  const tables = window.paperMindData?.tables || [];
  const sources = window.paperMindData?.sources || {};

  // Helper: Find table by ID
  const getTable = (id) => tables.find(t => t.id === id);

  // --- Word Cloud Logic ---
  const cloudDisplay = document.getElementById('cloud-display');
  const btn1965 = document.getElementById('btn-year-1965');
  const btn2015 = document.getElementById('btn-year-2015');

  const table1 = getTable('p2-table-1');
  let words1965 = [];
  let words2015 = [];

  if (table1 && table1.rows.length > 0) {
    const row = table1.rows[0];
    // Parse the long string of words
    const raw1965 = row.values['(a) Top 100 Words in 1965'] || '';
    const raw2015 = row.values['(b) Top 100 Words in 2015'] || '';

    // Split by comma, clean whitespace
    words1965 = raw1965.split(',').map(w => w.trim()).filter(w => w);
    words2015 = raw2015.split(',').map(w => w.trim()).filter(w => w);
  }

  function renderCloud(year) {
    cloudDisplay.innerHTML = '';
    const words = year === '1965' ? words1965 : words2015;

    // Highlight 'love' specifically as per text
    words.forEach(word => {
      const span = document.createElement('span');
      span.className = 'cloud-word';
      span.textContent = word;
      if (word.toLowerCase() === 'love') {
        span.classList.add('highlight');
        span.title = '1965 年最流行词汇';
      }
      cloudDisplay.appendChild(span);
    });
  }

  // Initial Render
  renderCloud('1965');

  // Event Listeners for Year Toggle
  btn1965.addEventListener('click', () => {
    btn1965.classList.add('active');
    btn1965.setAttribute('aria-pressed', 'true');
    btn2015.classList.remove('active');
    btn2015.setAttribute('aria-pressed', 'false');
    renderCloud('1965');
  });

  btn2015.addEventListener('click', () => {
    btn2015.classList.add('active');
    btn2015.setAttribute('aria-pressed', 'true');
    btn1965.classList.remove('active');
    btn1965.setAttribute('aria-pressed', 'false');
    renderCloud('2015');
  });

  // --- Swear Word Chart Logic ---
  const svgChart = document.getElementById('swear-chart');
  const table3 = getTable('p2-table-3');

  // Approximate data from table notes (visual reading)
  // Structure: [{year: 1970, bb: 0.0, msd: 0.0}, ...]
  const chartData = [];
  if (table3) {
    table3.rows.forEach(row => {
      const y = parseFloat(row.values['YEAR']);
      const bb = parseFloat(row.values['BB']);
      const msd = parseFloat(row.values['MSD']);
      if (!isNaN(y) && !isNaN(bb) && !isNaN(msd)) {
        chartData.push({ year: y, bb, msd });
      }
    });
  }

  function drawChart() {
    // Clear existing paths/groups except defs
    const existing = svgChart.querySelectorAll('.data-group');
    existing.forEach(e => e.remove());

    if (chartData.length === 0) return;

    const width = 400;
    const height = 200;
    const padding = 30;
    const plotW = width - padding * 2;
    const plotH = height - padding * 2;

    // Scales
    const minYear = 1970;
    const maxYear = 2010;
    const maxPercent = 2.5;

    const xScale = (year) => padding + ((year - minYear) / (maxYear - minYear)) * plotW;
    const yScale = (percent) => height - padding - (percent / maxPercent) * plotH;

    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.classList.add('data-group');

    // Axes
    const xAxis = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    xAxis.setAttribute('x1', padding);
    xAxis.setAttribute('y1', height - padding);
    xAxis.setAttribute('x2', width - padding);
    xAxis.setAttribute('y2', height - padding);
    xAxis.classList.add('axis-line');
    g.appendChild(xAxis);

    const yAxis = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    yAxis.setAttribute('x1', padding);
    yAxis.setAttribute('y1', padding);
    yAxis.setAttribute('x2', padding);
    yAxis.setAttribute('y2', height - padding);
    yAxis.classList.add('axis-line');
    g.appendChild(yAxis);

    // Labels
    const xLabel = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    xLabel.setAttribute('x', width / 2);
    xLabel.setAttribute('y', height - 5);
    xLabel.setAttribute('text-anchor', 'middle');
    xLabel.classList.add('axis-label');
    xLabel.textContent = 'YEAR';
    g.appendChild(xLabel);

    const yLabel = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    yLabel.setAttribute('x', 10);
    yLabel.setAttribute('y', height / 2);
    yLabel.setAttribute('transform', `rotate(-90, 10, ${height/2})`);
    yLabel.setAttribute('text-anchor', 'middle');
    yLabel.classList.add('axis-label');
    yLabel.textContent = 'Percent';
    g.appendChild(yLabel);

    // Paths
    // BB Line
    let bbPathD = '';
    let msdPathD = '';

    chartData.forEach((pt, i) => {
      const x = xScale(pt.year);
      const yBB = yScale(pt.bb);
      const yMSD = yScale(pt.msd);

      if (i === 0) {
        bbPathD += `M ${x} ${yBB}`;
        msdPathD += `M ${x} ${yMSD}`;
      } else {
        bbPathD += ` L ${x} ${yBB}`;
        msdPathD += ` L ${x} ${yMSD}`;
      }

      // Points
      const circleBB = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circleBB.setAttribute('cx', x);
      circleBB.setAttribute('cy', yBB);
      circleBB.setAttribute('r', 3);
      circleBB.classList.add('point');
      g.appendChild(circleBB);
    });

    const pathBB = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    pathBB.setAttribute('d', bbPathD);
    pathBB.classList.add('bb-line');
    g.appendChild(pathBB);

    const pathMSD = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    pathMSD.setAttribute('d', msdPathD);
    pathMSD.classList.add('msd-line');
    g.appendChild(pathMSD);

    svgChart.appendChild(g);
  }

  drawChart();

  // --- Source Button Handlers ---
  // Note: Actual source fetching is handled by host kernel via data-source attribute
  const sourceBtns = document.querySelectorAll('.source-btn');
  sourceBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      // No action needed here, kernel intercepts data-source
      // Visual feedback only
      btn.style.opacity = '0.7';
      setTimeout(() => btn.style.opacity = '1', 200);
    });
  });

  // --- Concept Button Handlers ---
  const conceptBtns = document.querySelectorAll('.concept-btn');
  conceptBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Kernel handles data-concept
    });
  });

  // --- Ask Button Handlers ---
  const askBtns = document.querySelectorAll('.ask-btn');
  askBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      // Kernel handles data-ask
    });
  });

})();
